        "supporting": ["oom_killed_current_revision", "oom_without_recent_rollout"],
        "contradicting": [],
        "missing": ["container_memory.peakBytes", "memory_data_available"],
        "status": "supported"
    },
    {
        "root_cause_class": "insufficient_evidence",
        "summary": "No evidence of memory leaks or node pressure, but OOM kills persist.",
        "supporting": ["evicted_for_node_memory"],
        "contradicting": ["oom_killed_current_revision"],
        "missing": ["container_memory.peakBytes", "memory_data_available"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "shop",
        "name": "sessions",
        "uid": "uid-deployment-sessions"
    },
    "params": {
        "containers": {
            "app": {
                "limits": {
                    "memory": "1.5Gi"
                }
            }
        }
    },
    "expected_effect": "Raise memory limit to 1.5Gi for the app container to prevent OOM kills.",
    "rationale": "The app reached 100% of its 1Gi memory limit before being OOMKilled, and no recent rollout explains this. Increasing the limit by 50% provides buffer for peak usage and potential growth.",
    "cited_evidence_ids": ["ev-container_memory", "ev-rollout_history", "ev-pod_states"],
    "cited_predicates": ["oom_killed_current_revision", "oom_without_recent_rollout", "memory_at_limit_before_kill"]
}
}

